// Repéré via la surveillance post-déploiement (29/09/2026) : quand supabase-js perd la
// session en tâche de fond (jeton expiré après une longue mise en veille de l'onglet,
// échec de rafraîchissement du refresh token...), il déclenche SIGNED_OUT, mais l'appli
// continuait silencieusement d'interroger la base avec la clé anon — écrans qui se
// vident sans le moindre message, toutes les 20 s (cf. syncDemarrer), jusqu'à ce que la
// personne recharge la page d'elle-même. On coupe désormais la synchro et on demande
// explicitement de recharger, plutôt que de laisser deviner pourquoi les données ont
// disparu. Le signOut initial de boot() (avant tout login, sur poste partagé) ne doit
// pas déclencher cet écran : currentUser n'est alors pas encore défini.
let _sessionExpireeGeree=false;
function gererDeconnexionInattendue(){
  if(!currentUser||_sessionExpireeGeree)return;
  _sessionExpireeGeree=true;
  if(_syncTimer)clearInterval(_syncTimer);
  const b=document.createElement('div');
  b.style.cssText='position:fixed;inset:0;z-index:99999;background:rgba(20,18,40,.75);display:flex;align-items:center;justify-content:center;padding:20px';
  b.innerHTML='<div style="background:#fff;border-radius:14px;padding:28px;max-width:360px;text-align:center;font-family:-apple-system,sans-serif">'
    +'<div style="font-size:32px;margin-bottom:10px">🔒</div>'
    +'<div style="font-weight:700;margin-bottom:8px;color:#1a1a1a">Session expirée</div>'
    +'<div style="color:#666;font-size:13.5px;margin-bottom:18px;line-height:1.5">Votre connexion a expiré (mise en veille prolongée). Les données affichées ne sont plus à jour — rechargez la page pour vous reconnecter.</div>'
    +'<button onclick="location.reload()" style="background:#3D3580;color:#fff;border:none;border-radius:8px;padding:11px 22px;font-weight:700;font-size:13.5px;cursor:pointer">Recharger</button>'
    +'</div>';
  document.body.appendChild(b);
}
