let cacheCreches=[],cacheDemandes=[],cacheReferents=[],cacheIncidents=[],cacheEnfants=[],cacheEvenements=[],cacheMessages=[],cacheConsignesLues=[],cacheEmployes=[],cachePartenaires=[],cacheEtablissements=[],cacheReseauFermetures=[],cacheDemandesMasquees=[],cacheDemandesTraitees=[],cacheHeuresValidations=[],cacheCommandes=[];

// creches.name porte la raison sociale complète ("Koalakids Toulon Brunet") ;
// les champs "lieu" en texte libre (événements, incidents, imports de planning)
// utilisent depuis toujours le libellé court ("Brunet"). On le dérive en
// retirant les préfixes d'enseigne/ville, ce qui reproduit exactement les
// libellés historiques Koala Kids ; repli sur le nom complet sinon.
function shortCrecheName(nom){
  return String(nom||'').replace(/^Koalakids\s+/i,'').replace(/^Toulon\s+/i,'').trim()||nom;
}
/** Reconstruit les <select> de "Crèche / Lieu" (e-lieu, ip-lieu, ec-lieu) à
 *  partir de cacheCreches, en conservant les options spéciales qui ne sont pas
 *  des crèches (Autre, Absent, Formation, Réunion). */
function populateLieuSelects(){
  if(!cacheCreches.length)return;
  const noms=cacheCreches.map(c=>shortCrecheName(c.name));
  const optsHtml=noms.map(n=>'<option value="'+escHtml(n)+'">'+escHtml(n)+'</option>').join('');
  const specs={
    'e-lieu':['<option value="">— Sélectionner —</option>',optsHtml,'<option value="Autre">Autre (préciser)</option>'],
    'ip-lieu':['<option value="">— Sélectionner —</option>',optsHtml],
    'ec-lieu':['<option value="">— Sélectionner —</option>',optsHtml,
      '<option value="Absent">Absent</option><option value="Formation">Formation</option><option value="Réunion">Réunion</option>'],
  };
  for(const id in specs){
    const sel=document.getElementById(id);
    if(!sel)continue;
    const cur=sel.value;
    sel.innerHTML=specs[id].join('');
    if(noms.includes(cur)||['Autre','Absent','Formation','Réunion'].includes(cur))sel.value=cur;
  }
}
