/* ── Fraîcheur des données importées ────────────────────────────────────────
   Savoir quand remonte le dernier import évite de travailler sur un planning périmé et
   permet d'anticiper le suivant. Le repère existant ne vivait que dans le localStorage de
   l'appareil ayant fait l'import : invisible pour les autres. On lit donc la date en base,
   avec repli sur le repère local — `created_at` n'existe pas forcément sur ces tables, et
   mieux vaut une date locale qu'une date fausse. */
function ipAgeLisible(d){
  const jours=Math.floor((new Date()-d)/86400000);
  if(jours<=0)return "aujourd'hui";
  if(jours===1)return 'hier';
  if(jours<7)return 'il y a '+jours+' jours';
  if(jours<14)return 'il y a une semaine';
  return 'il y a '+Math.floor(jours/7)+' semaines';
}
function ipLibelleFraicheur(prefixe,d){
  if(!d)return '';
  const jours=Math.floor((new Date()-d)/86400000);
  const couleur=jours>=7?'var(--orange-dark)':'var(--muted)';
  return '<span style="color:'+couleur+'">'+prefixe+' '
    +d.toLocaleDateString('fr-FR',{day:'2-digit',month:'2-digit'})+' à '
    +d.toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})
    +' · '+ipAgeLisible(d)+'</span>';
}
async function ipDateDernierImportPlanning(crecheId){
  try{
    const{data,error}=await sb.from('planning_equipe').select('created_at')
      .eq('creche_id',crecheId).not('import_batch_id','is',null)
      .order('created_at',{ascending:false}).limit(1);
    if(!error&&data&&data.length&&data[0].created_at)return new Date(data[0].created_at);
  }catch(e){/* colonne absente : on retombe sur le repère local */}
  try{
    const raw=localStorage.getItem('lastImportBatch_'+crecheId);
    if(raw){const d=new Date(JSON.parse(raw).date);if(!isNaN(d))return d;}
  }catch(e){}
  return null;
}
async function ipDateDernierePresence(crecheId,dateStrs){
  try{
    const ids=(cacheEnfants||[]).filter(e=>e.creche_id===crecheId).map(e=>e.id);
    if(!ids.length)return null;
    const{data,error}=await sb.from('presences').select('created_at')
      .in('presence_date',dateStrs).in('enfant_id',ids)
      .order('created_at',{ascending:false}).limit(1);
    if(!error&&data&&data.length&&data[0].created_at)return new Date(data[0].created_at);
  }catch(e){}
  return null;
}

function showLastImportZone(crecheId){
  const zone=document.getElementById('ip-last-import-zone');
  if(!zone)return;
  if(!crecheId){zone.style.display='none';return;}
  const raw=localStorage.getItem('lastImportBatch_'+crecheId);
  if(!raw){zone.style.display='none';return;}
  try{
    const info=JSON.parse(raw);
    const dateFr=new Date(info.date).toLocaleString('fr-FR',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'});
    document.getElementById('ip-last-import-text').innerHTML='📌 Dernier import effectué le <strong>'+dateFr+'</strong>. Si une erreur s\'est glissée, vous pouvez l\'annuler avant d\'en refaire un.';
    zone.style.display='';
  }catch(e){zone.style.display='none';}
}

async function resetLastImport(){
  const crecheId=!isDirection?currentProfile?.creche_id:document.getElementById('ip-referent').selectedOptions[0]?.dataset?.crecheId;
  if(!crecheId){alert('Crèche introuvable.');return;}
  const raw=localStorage.getItem('lastImportBatch_'+crecheId);
  if(!raw){alert('Aucun import récent trouvé pour cette crèche.');return;}
  const info=JSON.parse(raw);
  if(!confirm('Annuler le dernier import du '+new Date(info.date).toLocaleString('fr-FR')+' ?\n\nCela supprimera toutes les lignes créées par cet import, dans le planning équipe ET le planning individuel concerné.'))return;

  const btn=document.querySelector('#ip-last-import-zone .btn-cancel');
  if(btn){btn.disabled=true;btn.innerHTML='<i class="ti ti-loader"></i> Suppression…';}

  const{error:err1}=await sb.from('planning_equipe').delete().eq('creche_id',crecheId).eq('import_batch_id',info.batchId);
  let err2=null;
  if(info.referentId){
    const res=await sb.from('planning').delete().eq('referent_id',info.referentId).eq('import_batch_id',info.batchId);
    err2=res.error;
  }

  if(btn){btn.disabled=false;btn.innerHTML='<i class="ti ti-trash"></i> Réinitialiser ce dernier import';}

  if(err1||err2){
    console.error('[ResetImport]',err1?.message,err2?.message);
    showBanner('Erreur lors de la réinitialisation.','error');
    return;
  }

  localStorage.removeItem('lastImportBatch_'+crecheId);
  peInvalidateAll(crecheId);
  if(info.referentId)planningInvalidateAll(info.referentId);
  document.getElementById('ip-last-import-zone').style.display='none';
  showBanner('Dernier import annulé ✅');
  await renderPlanning();
}

function handleImportPlanningFile(event){
  const file=event.target.files[0];
  if(!file)return;
  const prenomRef=document.getElementById('ip-prenom').value.trim();
  const lieu=document.getElementById('ip-lieu').value;
  const referentId=document.getElementById('ip-referent').value;
  const crecheId=document.getElementById('ip-referent').selectedOptions[0]?.dataset?.crecheId;
  const year=parseInt(document.getElementById('ip-year').value)||new Date().getFullYear();

  if(!referentId){alert('Choisissez d\'abord le/la directeur/trice technique titulaire.');event.target.value='';return;}
  if(!prenomRef){alert('Indiquez son prénom dans le fichier.');event.target.value='';return;}
  if(!lieu){alert('Choisissez la crèche / lieu à appliquer.');event.target.value='';return;}

  document.getElementById('ip-filename').textContent='📄 '+file.name;

  const reader=new FileReader();
  reader.onload=function(e){
    try{
      const data=new Uint8Array(e.target.result);
      const wb=XLSX.read(data,{type:'array'});

      const allNames=ipExtractAllNames(wb);
      const byPerson={}; // prenom -> {events, warnings}
      allNames.forEach(name=>{byPerson[name]=ipExtractEvents(wb,name,lieu,year);});

      // S'assurer que le prénom de la directrice technique est bien inclus même s'il n'a pas été détecté automatiquement
      // (orthographe différente du premier mot de cellule, etc.)
      if(!byPerson[prenomRef]){byPerson[prenomRef]=ipExtractEvents(wb,prenomRef,lieu,year);}

      _ipPendingByPerson=byPerson;
      _ipPendingReferentId=referentId;
      _ipPendingReferentPrenom=prenomRef;
      _ipPendingCrecheId=crecheId;

      renderImportPlanningPreview(byPerson,prenomRef);
    }catch(err){
      document.getElementById('ip-result').style.display='';
      document.getElementById('ip-result').innerHTML='<div style="color:var(--red);font-size:13px">⚠ Erreur de lecture du fichier : '+err.message+'</div>';
    }
  };
  reader.readAsArrayBuffer(file);
}

const IP_TYPE_LABELS={presence:'🏠 Présence',absent:'❌ Absent',conge:'🌴 Congé',formation:'📚 Formation',reunion:'👥 Réunion',ferie:'🎌 Férié',vacances:'🏖️ Vacances'};
const IP_LABELS_PLAIN={presence:'Présence',absent:'Absent',conge:'Congé',formation:'Formation',reunion:'Réunion',ferie:'Férié',vacances:'Vacances'};

function renderImportPlanningPreview(byPerson,prenomRef){
  document.getElementById('ip-step-config').style.display='none';
  document.getElementById('ip-step-preview').style.display='';

  const names=Object.keys(byPerson);
  const totalEvents=names.reduce((s,n)=>s+byPerson[n].events.length,0);
  const allWarnings=names.flatMap(n=>byPerson[n].warnings);

  if(totalEvents===0){
    document.getElementById('ip-preview-summary').innerHTML='<div style="color:var(--orange);font-size:13px">⚠ Aucun créneau détecté dans ce fichier. Vérifiez le format.</div>';
    document.getElementById('ip-preview-list').innerHTML='';
    document.getElementById('ip-btn-confirm').style.display='none';
  }else{
    document.getElementById('ip-preview-summary').innerHTML=
      '<div style="font-size:13px;color:var(--koala);font-weight:700">✅ '+names.length+' salarié(e)(s) détecté(e)(s), '+totalEvents+' événement(s) au total</div>'+
      '<div style="font-size:11px;color:var(--ink2);margin-top:4px">"'+prenomRef+'" recevra en plus son planning individuel personnel.</div>'+
      '<div style="font-size:11px;color:var(--orange);margin-top:4px">⚠ Les jours déjà renseignés seront remplacés par les données de ce fichier.</div>';

    document.getElementById('ip-preview-list').innerHTML=names.map(name=>{
      const{events}=byPerson[name];
      const isRef=ipNormStr(name)===ipNormStr(prenomRef);
      const badge=isRef?'<span style="font-size:10px;background:var(--koala-light);color:var(--koala);padding:2px 7px;border-radius:8px;margin-left:6px">directeur/trice technique — planning individuel + équipe</span>':'<span style="font-size:10px;background:#f0f0f5;color:#888;padding:2px 7px;border-radius:8px;margin-left:6px">planning équipe</span>';
      const rows=events.map(e=>{
        const dateFr=new Date(e.dateISO+'T00:00:00').toLocaleDateString('fr-FR',{weekday:'short',day:'2-digit',month:'2-digit'});
        const titre=e.merged?e.mergedLabel:(IP_TYPE_LABELS[e.type]+' '+(e.lieu?'@ '+e.lieu:''));
        const horaire=!e.merged&&e.hdebut?('<br><span style="color:var(--ink2)">'+e.hdebut+'–'+e.hfin+'</span>'):'';
        return '<div style="padding:5px 10px;border-bottom:1px solid var(--border);font-size:11px;display:flex;justify-content:space-between;gap:8px"><div>'+dateFr+' — '+titre+horaire+'</div><span style="color:#bbb;white-space:nowrap">"'+e.sourceCell+'"</span></div>';
      }).join('');
      return '<details style="border-bottom:1px solid var(--border)"><summary style="padding:8px 12px;cursor:pointer;font-size:12px;font-weight:700;color:var(--koala)">'+name+badge+' — '+events.length+' jour(s)</summary>'+rows+'</details>';
    }).join('');
    document.getElementById('ip-btn-confirm').style.display='';
  }

  document.getElementById('ip-preview-warnings').innerHTML=allWarnings.length?
    '<div style="font-size:11px;color:var(--orange);background:var(--amber-lt);padding:8px 10px;border-radius:8px;max-height:100px;overflow-y:auto">⚠ '+allWarnings.length+' avertissement(s) :<br>'+allWarnings.join('<br>')+'</div>':'';
}

async function confirmImportPlanning(){
  if(!_ipPendingByPerson||!_ipPendingReferentId||!_ipPendingCrecheId){
    if(!_ipPendingCrecheId){
      document.getElementById('ip-result').style.display='';
      document.getElementById('ip-result').innerHTML='<div style="color:var(--red);font-size:13px">⚠ Impossible de déterminer la crèche du/de la directeur/trice technique sélectionné — vérifiez sa fiche dans l\'annuaire.</div>';
    }
    return;
  }
  const btn=document.getElementById('ip-btn-confirm');
  btn.disabled=true;btn.innerHTML='<i class="ti ti-loader"></i> Import en cours…';

  const batchId=(crypto?.randomUUID)?crypto.randomUUID():('batch-'+Date.now()+'-'+Math.random().toString(36).slice(2));
  let savedRef=0,savedEquipe=0,failed=0;

  for(const name in _ipPendingByPerson){
    const{events}=_ipPendingByPerson[name];
    const isRef=ipNormStr(name)===ipNormStr(_ipPendingReferentPrenom);

    for(const e of events){
      const semaine=mondayOfISO(e.dateISO);
      const label=e.merged?e.mergedLabel:(e.lieu||IP_LABELS_PLAIN[e.type]||e.type);

      // Toujours enregistrer dans le planning équipe (toutes les salariées, y compris la directrice technique)
      const{error:errEquipe}=await sb.from('planning_equipe').upsert({
        creche_id:_ipPendingCrecheId,prenom:name,semaine,jour:e.day,type:e.type,label,
        lieu:e.lieu||null,hdebut:e.hdebut||null,hfin:e.hfin||null,pause:e.pause||null,
        source_cell:e.sourceCell,creneau_label:e.merged?null:e.sourceCreneauLabel,
        import_batch_id:batchId
      },{onConflict:'creche_id,prenom,semaine,jour'});
      if(errEquipe){console.error('[PlanningEquipe]',errEquipe.message);failed++;}else{savedEquipe++;}

      // En plus, si c'est la directrice technique titulaire, enregistrer aussi dans son planning individuel.
      // On supprime d'abord tout événement existant ce jour-là (l'upsert sur slot=NULL ne déduplique
      // pas correctement en SQL, NULL n'étant jamais égal à NULL pour une contrainte unique), puis on
      // insère la nouvelle version — ce qui correspond au comportement "remplacer" annoncé dans l'aperçu.
      if(isRef){
        await sb.from('planning').delete().eq('referent_id',_ipPendingReferentId).eq('semaine',semaine).eq('jour',e.day).is('slot',null);
        const ok=await planningSave(_ipPendingReferentId,semaine,{
          day:e.day,slot:null,type:e.type,label,lieu:e.lieu,
          hdebut:e.hdebut,hfin:e.hfin,pause:e.pause,detachType:'',detachDesc:'',multi:true,batchId
        });
        if(ok)savedRef++;else failed++;
      }
    }
  }

  // Mémorise le batch_id du dernier import pour cette crèche, afin que le bouton "Réinitialiser" sache quoi cibler
  localStorage.setItem('lastImportBatch_'+_ipPendingCrecheId,JSON.stringify({batchId,referentId:_ipPendingReferentId,date:new Date().toISOString()}));

  btn.disabled=false;btn.innerHTML='<i class="ti ti-check"></i> Importer ces événements';
  document.getElementById('ip-result').style.display='';
  document.getElementById('ip-result').innerHTML=failed?
    '<div style="color:var(--orange);font-size:13px">⚠ Import partiel : '+savedEquipe+' jour(s) équipe + '+savedRef+' jour(s) directeur/trice technique enregistrés, '+failed+' échec(s). Voir la console.</div>':
    '<div style="color:var(--koala);font-size:13px;font-weight:700">✅ Import terminé : '+savedEquipe+' jour(s) dans le planning équipe, dont '+savedRef+' aussi dans le planning individuel de '+_ipPendingReferentPrenom+'.</div>';
  document.getElementById('ip-btn-confirm').style.display='none';

  await renderPlanning();
}

// ── SUPABASE PLANNING ──
const COORD_REF_ID='b608fd68-3c86-485f-b55c-75f465b03650';
let _planningCache={};
async function planningLoad(referentId,semaineDate){
  const k=referentId+'_'+semaineDate;
  if(_planningCache[k])return _planningCache[k];
  const{data,error}=await sb.from('planning').select('*').eq('referent_id',referentId).eq('semaine',semaineDate);
  if(error){console.error('[Planning]',error.message);return[];}
  _planningCache[k]=data||[];return _planningCache[k];
}
function planningInvalidate(r,s){delete _planningCache[r+'_'+s];}
function planningInvalidateAll(referentId){
  Object.keys(_planningCache).forEach(k=>{if(k.startsWith(referentId+'_'))delete _planningCache[k];});
}
async function planningSave(referentId,semaineDate,ev){
  const row={referent_id:referentId,semaine:semaineDate,jour:ev.day,slot:ev.slot!==undefined?ev.slot:null,
    type:ev.type,label:ev.label||null,lieu:ev.lieu||null,hdebut:ev.hdebut||null,hfin:ev.hfin||null,
    pause:ev.pause||null,detach_type:ev.detachType||null,detach_desc:ev.detachDesc||null,
    import_batch_id:ev.batchId||null};

  // Modification d'un événement existant précis (édition) : update ciblé par id, jamais d'upsert sur jour/slot
  if(ev.id){
    const{error}=await sb.from('planning').update(row).eq('id',ev.id);
    if(error){console.error('[Planning] update:',error.message);return false;}
    planningInvalidate(referentId,semaineDate);return true;
  }

  // Nouvel événement pour le planning directeur technique individuel (multi-événements/jour autorisé) : insert pur
  if(ev.multi){
    const{error}=await sb.from('planning').insert(row);
    if(error){console.error('[Planning] insert:',error.message);return false;}
    planningInvalidate(referentId,semaineDate);return true;
  }

  // Comportement existant (coordinateur, slot 0/1, ou import) : upsert sur jour/slot
  const{error}=await sb.from('planning').upsert(row,{onConflict:'referent_id,semaine,jour,slot'});
  if(error){console.error('[Planning] save:',error.message);return false;}
  planningInvalidate(referentId,semaineDate);return true;
}
async function planningDeleteRow(id,referentId,semaineDate){
  const{error}=await sb.from('planning').delete().eq('id',id);
  if(error){console.error('[Planning] del:',error.message);return false;}
  planningInvalidate(referentId,semaineDate);return true;
}
async function delPlanningEvent(id,referentId,semaine){await planningDeleteRow(id,referentId,semaine);await renderPlanning();}

// ── SAVE EVENT REFERENT ──
async function saveEvent(){
  const type=document.getElementById('e-type').value;
  const fullWeek=document.getElementById('e-full-week').checked;
  const dayVal=parseInt(document.getElementById('e-day').value);
  const userId=currentProfile?.id||currentUser?.id;
  if(!userId){alert('Erreur : profil non chargé.');return;}
  let hdebut='',hfin='',pause='';
  if(!['absent','conge','ferie','vacances'].includes(type)){
    hdebut=document.getElementById('e-hdebut').value;hfin=document.getElementById('e-hfin').value;const pd=document.getElementById('e-pause-debut').value;
    const pf=pd?document.getElementById('e-pause-fin')?.value:'';
    pause=pd&&pf?pd+'-'+pf:'';
    if(hdebut>=hfin){alert("L'heure de fin doit être après l'heure de début.");return;}
  }
  let lieu='';
  if(['presence','formation','reunion'].includes(type)){
    const s=document.getElementById('e-lieu').value;
    lieu=s==='Autre'?document.getElementById('e-lieu-autre').value.trim():s;
    if(!lieu){alert('Indiquez un lieu.');return;}
  }
  let detachType='',detachDesc='';
  if(type==='detachement'){detachType=document.getElementById('e-detach-type').value;detachDesc=document.getElementById('e-detach-desc').value.trim();}
  const labels={presence:'Présence',absent:'Absent',conge:'Congé',formation:'Formation',reunion:'Réunion',detachement:'Détachement',ferie:'Férié',vacances:'Vacances'};
  const label=lieu||(detachType||labels[type]||type);
  const ws=weekStart();const semaine=ipDateToLocalISO(ws);
  const days=fullWeek?[0,1,2,3,4]:[dayVal];
  const btn=document.querySelector('#modal-event-wrap .btn-primary');
  if(btn){btn.disabled=true;btn.innerHTML='<i class="ti ti-loader"></i> Enregistrement…';}
  if(editingPlanningEventId){
    // Édition d'un événement existant précis : update ciblé, jamais de doublon
    await planningSave(userId,semaine,{id:editingPlanningEventId,day:dayVal,slot:null,type,label,lieu,hdebut,hfin,pause,detachType,detachDesc});
  }else{
    // Nouvel événement : insert pur pour autoriser plusieurs événements le même jour
    for(const d of days)await planningSave(userId,semaine,{day:d,slot:null,type,label,lieu,hdebut,hfin,pause,detachType,detachDesc,multi:true});
  }
  if(btn){btn.disabled=false;btn.innerHTML='<i class="ti ti-check"></i> Enregistrer';}
  editingPlanningEventId=null;
  closeModal('modal-event-wrap');await renderPlanning();
}

// Le planning « coordinateur » est celui de l'utilisateur connecté lorsqu'il est direction.
// Plusieurs comptes direction peuvent coexister : on ne cherche donc JAMAIS par nom ni par
// simple find(role==='direction'), qui renverrait une direction arbitraire.
function getCoordRef(){
  if(currentProfile?.role==='direction')return currentProfile;
  return cacheReferents.find(r=>r.id===COORD_REF_ID)
      || cacheReferents.find(r=>r.role==='direction')
      || null;
}

// ── SAVE EVENT COORDINATEUR ──
async function saveEventCoord(){
  const coord=getCoordRef();
  if(!coord){alert('Coordinateur introuvable.');return;}
  const ws=weekStart();const semaine=ipDateToLocalISO(ws);
  const type=document.getElementById('ec-type').value;
  const creche=document.getElementById('ec-lieu').value;
  const libre=(document.getElementById('ec-type-libre').value||'').trim();
  const ville=(document.getElementById('ec-ville').value||'').trim();
  if(type==='autre'&&!libre){alert('Précisez l\'intitulé libre.');return;}
  // Libellé affiché dans la grille : l'intitulé libre s'il existe, sinon la crèche, sinon le type.
  const label=libre||creche||type;
  // Lieu retenu pour les IK : la ville saisie prime sur la crèche sélectionnée.
  const lieu=ville||creche||'';
  const day=parseInt(document.getElementById('ec-day').value);
  const slot=parseInt(document.getElementById('ec-slot').value);
  const btn=document.querySelector('#modal-event-coord-wrap .btn-primary');
  if(btn){btn.disabled=true;btn.innerHTML='<i class="ti ti-loader"></i> Enregistrement…';}
  let ok=await planningSave(coord.id,semaine,{day,slot,type,label,lieu});
  // Repli si la colonne « type » de la table planning n'accepte pas encore la valeur « autre » :
  // on conserve l'intitulé libre dans label et on retombe sur « detachement ».
  if(!ok&&type==='autre')ok=await planningSave(coord.id,semaine,{day,slot,type:'detachement',label,lieu});
  if(btn){btn.disabled=false;btn.innerHTML='<i class="ti ti-check"></i> Enregistrer';}
  if(!ok)alert('Enregistrement impossible — vérifiez la connexion.');
  closeModal('modal-event-coord-wrap');await renderPlanning();
}

// ── GRILLES ──
function getPlanningGrid(events,referentId,semaine,editable){
  const ws=weekStart();const fmt=d=>d.toLocaleDateString('fr-FR',{day:'2-digit',month:'2-digit'});
  const days5=Array.from({length:5},(_,i)=>{const d=new Date(ws);d.setDate(ws.getDate()+i);return d;});
  const _pgCrecheId=(cacheReferents.find(r=>r.id===referentId)||{}).creche_id;
  let html='<div class="pg-hd"></div>';
  days5.forEach((d,i)=>{
    const _fermD=fermetureAt(_pgCrecheId,ipDateToLocalISO(d));
    html+='<div class="pg-hd"'+(_fermD?' style="background:var(--red-l,#FDE8E8);color:var(--red,#C62828)" title="'+escHtml(fermetureLabel(_fermD))+'"':'')+'>'+DAYS[i]+'<br><span style="font-size:10px;font-weight:400;opacity:0.7">'+fmt(d)+'</span>'+(_fermD?'<br><span style="font-size:9.5px;font-weight:800"><i class="ti ti-door-off"></i> Fermé</span>':'')+'</div>';
  });
  html+='<div class="pg-time" style="font-size:10px">Journée</div>';
  days5.forEach((_,di)=>{
    const evs=events.filter(e=>(e.jour===di||e.day===di)&&(e.slot===null||e.slot===undefined));
    html+='<div class="'+(editable?'pg-cell':'pg-cell-ro')+'">';
    if(evs.length){
      const labels={presence:'Présence',absent:'Absent',conge:'Congé',formation:'Formation',reunion:'Réunion',detachement:'Détachement',ferie:'Férié',vacances:'Vacances'};
      evs.forEach(ev=>{
        const titre=ev.label||labels[ev.type]||ev.type;
        const del=editable?'<span class="pg-del" onclick="event.stopPropagation();delPlanningEvent(\''+ev.id+'\',\''+referentId+'\',\''+semaine+'\')"><i class="ti ti-x"></i></span>':'';
        let detail='';
        if(ev.hdebut&&ev.hfin)detail+='<div style="font-size:10px;margin-top:3px;opacity:0.85">⏱ '+formatHeure(ev.hdebut)+'–'+formatHeure(ev.hfin)+'</div>';
        if(ev.pause)detail+='<div style="font-size:10px;opacity:0.7">☕ '+ev.pause+'</div>';
        if(ev.detach_desc||ev.detachDesc)detail+='<div style="font-size:10px;margin-top:2px;opacity:0.8;font-style:italic">'+(ev.detach_desc||ev.detachDesc)+'</div>';
        html+='<div class="pg-card '+ev.type+'" '+(editable?'onclick="event.stopPropagation();openEventAt('+di+',\''+ev.id+'\')"':'')+'>'+del+titre+detail+'</div>';
      });
      if(editable)html+='<div class="pg-add-more" onclick="event.stopPropagation();openEventAt('+di+')" title="Ajouter un autre événement ce jour"><i class="ti ti-plus"></i></div>';
    }else if(editable){html+='<div class="pg-add" onclick="openEventAt('+di+')">+ ajouter</div>';}
    else{html+='<div style="text-align:center;padding:1rem;color:#ddd;font-size:11px">—</div>';}
    html+='</div>';
  });
  return html;
}

// Libellé principal d'une case du planning coordinateur : l'intitulé saisi, sinon le lieu.
function pgEvLabel(e){return e.label||e.lieu||e.type;}
// Ville affichée en sous-ligne quand elle diffère du libellé (déplacement hors crèche).
function pgEvVille(e){
  if(!e.lieu||e.lieu===e.label)return'';
  return'<span class="pg-ev-ville">📍 '+e.lieu+'</span>';
}

function getPlanningGridSimple(events,coordId,semaine,crecheIdHint){
  const ws=weekStart();const fmt=d=>d.toLocaleDateString('fr-FR',{day:'2-digit',month:'2-digit'});
  const days5=Array.from({length:5},(_,i)=>{const d=new Date(ws);d.setDate(ws.getDate()+i);return d;});
  const editable=!!coordId;
  const _pgsCrecheId=crecheIdHint||(cacheReferents.find(r=>r.id===coordId)||{}).creche_id;
  let html='<div class="pg-hd"></div>';
  days5.forEach((d,i)=>{
    const _fermD=fermetureAt(_pgsCrecheId,ipDateToLocalISO(d));
    html+='<div class="pg-hd"'+(_fermD?' style="background:var(--red-l,#FDE8E8);color:var(--red,#C62828)" title="'+escHtml(fermetureLabel(_fermD))+'"':'')+'>'+DAYS[i]+'<br><span style="font-size:10px;font-weight:400;opacity:0.7">'+fmt(d)+'</span>'+(_fermD?'<br><span style="font-size:9.5px;font-weight:800"><i class="ti ti-door-off"></i> Fermé</span>':'')+'</div>';
  });
  ['Matin','Après-midi'].forEach((slot,si)=>{
    html+='<div class="pg-time">'+slot+'</div>';
    days5.forEach((_,di)=>{
      const evs=events.filter(e=>(e.jour===di||e.day===di)&&e.slot===si);
      if(editable){
        html+='<div class="pg-cell" onclick="openCoordEventAt('+di+','+si+')">';
        if(!evs.length)html+='<span style="font-size:10px;color:#ccc">+ ajouter</span>';
        evs.forEach(e=>{html+='<div class="pg-ev '+e.type+'" onclick="event.stopPropagation();delPlanningEvent(\''+e.id+'\',\''+coordId+'\',\''+semaine+'\')">'+
          pgEvLabel(e)+' <i class="ti ti-x" style="font-size:10px;opacity:0.8"></i>'+pgEvVille(e)+'</div>';});
      }else{
        html+='<div class="pg-cell-ro">';
        if(!evs.length)html+='<div style="text-align:center;padding:0.5rem;color:#ddd;font-size:11px">—</div>';
        else evs.forEach(e=>{html+='<div class="pg-ev '+e.type+'" style="opacity:0.85">'+pgEvLabel(e)+pgEvVille(e)+'</div>';});
      }
      html+='</div>';
    });
  });
  return html;
}

// ── RENDER PLANNING ──
async function renderPlanning(){
  const ws=weekStart();const semaine=ipDateToLocalISO(ws);
  const fmt=d=>d.toLocaleDateString('fr-FR',{day:'2-digit',month:'2-digit'});
  const days5=Array.from({length:5},(_,i)=>{const d=new Date(ws);d.setDate(ws.getDate()+i);return d;});
  document.getElementById('week-label').textContent=fmt(days5[0])+' – '+fmt(days5[4])+' (S'+hebdoNumSemaine(days5[0])+')';
  const iAmCoord=currentProfile?.role==='direction';
  const userId=currentProfile?.id||currentUser?.id||'dir';
  const coord=getCoordRef();
  const addBtn=document.getElementById('planning-add-btn');
  const refLabel=document.getElementById('planning-ref-label');
  const refSelect=document.getElementById('planning-ref-select');
  const topBadge=document.getElementById('planning-top-badge');
  const coordBadge=document.getElementById('planning-coord-badge');
  const coordAdd=document.getElementById('planning-coord-add-btn');
  const coordLabel=document.getElementById('planning-coord-label');
  const coordSelect=document.getElementById('planning-coord-select');
  const importBtn=document.getElementById('planning-import-btn');
  const gridMine=document.getElementById('planning-grid-mine');
  const gridOther=document.getElementById('planning-grid-other');
  if(iAmCoord){
    if(addBtn)addBtn.style.display='none';
    if(importBtn)importBtn.style.display='none';
    if(refLabel)refLabel.style.display='none';
    if(refSelect){refSelect.style.display='';
      if(refSelect.options.length<=1){
        const refs=cacheReferents.filter(r=>r.role!=='direction');
        refSelect.innerHTML='<option value="">-- Choisir un/une directeur/trice technique --</option>'+refs.map(r=>'<option value="'+r.id+'">'+r.name+'</option>').join('');
      }
    }
    if(topBadge){topBadge.textContent='👁 Lecture seule';topBadge.style.background='#f0f0f5';topBadge.style.color='#888';}
    const selectedId=refSelect?.value;
    if(gridMine){
      if(!selectedId)gridMine.innerHTML='<div style="text-align:center;padding:2rem;color:#bbb;font-size:13px">Sélectionnez un/une directeur/trice technique</div>';
      else{if(!_syncSilencieuse)gridMine.innerHTML='<div style="padding:1rem;text-align:center;color:#bbb;font-size:12px">Chargement…</div>';
        const evs=await planningLoad(selectedId,semaine);gridMine.innerHTML=getPlanningGrid(evs,selectedId,semaine,false);}
    }
    // Bloc du bas : tout compte direction peut choisir de voir/éditer SON propre planning,
    // ou de consulter (lecture seule) celui d'un autre membre de la direction (ex. le coordinateur
    // principal). Ceci corrige le cas où un autre compte "direction" (ex. Andy Janin, Cyril Gabriel)
    // ne voyait jamais que son propre planning et jamais celui du coordinateur.
    const dirAccounts=cacheReferents.filter(r=>r.role==='direction');
    if(coordSelect){
      coordSelect.style.display=dirAccounts.length>1?'':'none';
      if(coordLabel)coordLabel.textContent=dirAccounts.length>1?'Planning direction':'Planning du coordinateur';
      const opts=dirAccounts.map(r=>'<option value="'+r.id+'">'+r.name+(r.id===currentProfile.id?' (moi)':'')+'</option>').join('');
      if(coordSelect.options.length<=1||coordSelect.getAttribute('data-count')!=String(dirAccounts.length)){
        coordSelect.innerHTML=opts;
        coordSelect.value=currentProfile.id;
        coordSelect.setAttribute('data-count',String(dirAccounts.length));
      }
    }
    const viewedCoordId=(coordSelect&&coordSelect.value)||currentProfile.id;
    const viewedCoord=dirAccounts.find(r=>r.id===viewedCoordId)||currentProfile;
    const isOwnCoordPlanning=viewedCoordId===currentProfile.id;
    if(coordBadge){
      if(isOwnCoordPlanning){coordBadge.textContent='✏️ Modifiable';coordBadge.style.background='var(--koala-light)';coordBadge.style.color='var(--koala)';}
      else{coordBadge.textContent='👁 Lecture seule';coordBadge.style.background='#f0f0f5';coordBadge.style.color='#888';}
    }
    if(coordAdd)coordAdd.style.display=isOwnCoordPlanning?'':'none';
    if(gridOther){
      if(!viewedCoord)gridOther.innerHTML='<div style="text-align:center;padding:2rem;color:#bbb;font-size:13px">—</div>';
      else{if(!_syncSilencieuse)gridOther.innerHTML='<div style="padding:1rem;text-align:center;color:#bbb;font-size:12px">Chargement…</div>';
        const cEvs=await planningLoad(viewedCoord.id,semaine);gridOther.innerHTML=getPlanningGridSimple(cEvs,isOwnCoordPlanning?viewedCoord.id:null,semaine,viewedCoord.creche_id);}
    }
  }else{
    if(!userId||userId==='dir'){setTimeout(()=>renderPlanning(),500);return;}
    if(addBtn)addBtn.style.display='';
    if(importBtn)importBtn.style.display='';
    if(refSelect)refSelect.style.display='none';
    if(refLabel){refLabel.style.display='';refLabel.textContent=currentProfile?.name||'Mon planning';}
    if(topBadge){topBadge.textContent='✏️ Modifiable';topBadge.style.background='var(--koala-light)';topBadge.style.color='var(--koala)';}
    if(gridMine){if(!_syncSilencieuse)gridMine.innerHTML='<div style="padding:1rem;text-align:center;color:#bbb;font-size:12px">Chargement…</div>';
      const evs=await planningLoad(userId,semaine);gridMine.innerHTML=getPlanningGrid(evs,userId,semaine,true);}
    if(coordBadge){coordBadge.textContent='👁 Lecture seule';coordBadge.style.background='#f0f0f5';coordBadge.style.color='#888';}
    if(coordAdd)coordAdd.style.display='none';
    if(gridOther){
      if(!coord)gridOther.innerHTML='<div style="text-align:center;padding:2rem;color:#bbb;font-size:13px">Coordinateur non disponible</div>';
      else{if(!_syncSilencieuse)gridOther.innerHTML='<div style="padding:1rem;text-align:center;color:#bbb;font-size:12px">Chargement…</div>';
        const cEvs=await planningLoad(coord.id,semaine);gridOther.innerHTML=getPlanningGridSimple(cEvs,null,semaine,coord.creche_id);}
    }
  }
  await renderPlanningEquipe();
}

// ── PLANNING ÉQUIPE (toutes les salariées d'une crèche, importé depuis Excel) ──
let _peCache={};
async function peLoad(crecheId,semaineDate){
  const k=crecheId+'_'+semaineDate;
  if(_peCache[k])return _peCache[k];
  const{data,error}=await sb.from('planning_equipe').select('*').eq('creche_id',crecheId).eq('semaine',semaineDate);
  if(error){console.error('[PlanningEquipe]',error.message);return[];}
  _peCache[k]=data||[];return _peCache[k];
}
function peInvalidate(crecheId,semaineDate){delete _peCache[crecheId+'_'+semaineDate];}
function peInvalidateAll(crecheId){
  Object.keys(_peCache).forEach(k=>{if(k.startsWith(crecheId+'_'))delete _peCache[k];});
}

// ── SYNCHRONISATION AVEC LE PLANNING INDIVIDUEL DE LA DIRECTRICE TECHNIQUE ──
// Comme lors d'un import Excel/PDF : toute personne du planning équipe qui
// correspond à la directrice technique titulaire de la crèche voit aussi son
// planning individuel (table "planning", celui affiché en haut de l'onglet
// et sur collaborateur.html) mis à jour automatiquement.
function peFindReferentIdForPrenom(crecheId,prenom,silent){
  const target=ipNormStr(prenom);
  if(!target)return null;
  // Clé de rapprochement, par ordre de priorité : le prénom réglé explicitement sur
  // la fiche directeur technique (referents.planning_nom — l'équivalent, pour ce
  // module, du prénom qu'on choisissait déjà lors d'un import Excel/PDF), sinon
  // celui de la fiche employé liée (employes.planning_nom, cf.
  // sql/collaborateurs_planning_nom.sql), sinon le nom de la fiche referents.
  const ref=(cacheReferents||[]).find(r=>{
    if(r.creche_id!==crecheId)return false;
    if(r.planning_nom)return ipNormStr(r.planning_nom)===target;
    const emp=r.employe_id?(cacheEmployes||[]).find(e=>e.id===r.employe_id):null;
    if(emp&&emp.planning_nom)return ipNormStr(emp.planning_nom)===target;
    if(!r.name)return false;
    // Tolère "Prénom Nom" comme "Nom Prénom" : on compare à chaque mot du nom complet.
    return String(r.name).trim().split(/\s+/).some(w=>ipNormStr(w)===target);
  });
  if(!ref&&!silent)console.warn('[PlanningEquipe] Aucun directeur/trice technique de cette crèche ne correspond au prénom "'+prenom+'" — son planning individuel ne sera pas mis à jour. Vérifiez l\'Annuaire des directeurs/trices techniques (ou employes.planning_nom en cas d\'homonymie).');
  return ref?ref.id:null;
}
async function peSyncReferentPlanning(crecheId,semaine,jour,prenom,ev){
  const referentId=peFindReferentIdForPrenom(crecheId,prenom);
  if(!referentId)return;
  await sb.from('planning').delete().eq('referent_id',referentId).eq('semaine',semaine).eq('jour',jour).is('slot',null);
  await planningSave(referentId,semaine,{
    day:jour,slot:null,type:ev.type||'presence',label:ev.label||prenom,lieu:ev.lieu||null,
    hdebut:ev.hdebut||null,hfin:ev.hfin||null,pause:ev.pause||null,detachType:'',detachDesc:'',multi:true
  });
  planningInvalidate(referentId,semaine);
}
async function peUnsyncReferentPlanning(crecheId,semaine,jour,prenom){
  const referentId=peFindReferentIdForPrenom(crecheId,prenom);
  if(!referentId)return;
  await sb.from('planning').delete().eq('referent_id',referentId).eq('semaine',semaine).eq('jour',jour).is('slot',null);
  planningInvalidate(referentId,semaine);
}

// Comme lors d'un import Excel/PDF, où l'on choisissait explicitement le prénom de la
// directrice technique dans le fichier : ce réglage (referents.planning_nom) permet
// de fiabiliser le rapprochement automatique quand le prénom du planning équipe ne
// correspond pas exactement au nom de sa fiche.
let _peRefNomTargetId=null;
function peRenderRefNomRow(crecheId,editable){
  const row=document.getElementById('pe-ref-nom-row');
  if(!row)return;
  const ref=editable?(cacheReferents||[]).find(r=>r.creche_id===crecheId):null;
  if(!ref){row.style.display='none';_peRefNomTargetId=null;return;}
  _peRefNomTargetId=ref.id;
  document.getElementById('pe-ref-nom-label').textContent='Prénom de '+ref.name+' dans ce planning :';
  document.getElementById('pe-ref-nom-input').value=ref.planning_nom||'';
  document.getElementById('pe-ref-nom-input').placeholder=ref.name?String(ref.name).trim().split(/\s+/)[0]:'';
  row.style.display='flex';
}
async function peSaveRefPlanningNom(){
  if(!_peRefNomTargetId)return;
  const val=document.getElementById('pe-ref-nom-input').value.trim();
  const ok=await dbUpdate('referents',_peRefNomTargetId,{planning_nom:val||null});
  if(!ok){showBanner('Erreur lors de l\'enregistrement.','error');return;}
  const ref=(cacheReferents||[]).find(r=>r.id===_peRefNomTargetId);
  if(ref)ref.planning_nom=val||null;
  showBanner('Prénom enregistré ✅');
}

// Répercute sur le planning individuel du directeur technique les créneaux déjà présents
// dans Planning équipe cette semaine — utile quand ils ont été ajoutés avant que le
// rapprochement (nom de la fiche, ou pe-ref-nom-input) ne soit correctement réglé.
async function peResyncWeek(){
  if(!_peCurCrecheId||!_peCurSemaine)return;
  const btn=document.getElementById('pe-resync-btn');
  if(btn){btn.disabled=true;btn.innerHTML='<i class="ti ti-loader"></i> Resynchronisation…';}
  const rows=await peLoad(_peCurCrecheId,_peCurSemaine);
  let nb=0;
  for(const r of rows){
    if(peFindReferentIdForPrenom(_peCurCrecheId,r.prenom)){
      await peSyncReferentPlanning(_peCurCrecheId,_peCurSemaine,r.jour,r.prenom,{type:r.type,label:r.label||r.prenom,lieu:r.lieu,hdebut:r.hdebut,hfin:r.hfin,pause:r.pause});
      nb++;
    }
  }
  if(btn){btn.disabled=false;btn.innerHTML='<i class="ti ti-refresh"></i> Resynchroniser';}
  if(nb)await renderPlanning();
  showBanner(nb?nb+' créneau(x) répercuté(s) sur le planning individuel ✅':'Aucun créneau de cette semaine ne correspond à un/une directeur/trice technique connu.',nb?undefined:'error');
}

// ── ÉDITION D'UNE CASE DU TABLEAU ÉQUIPE (remplace/ajoute/supprime un nom sur un créneau) ──
let _peEditCtx=null; // {eventId|null, creneauLabel, jour, crecheId, semaine}

// Remplit la liste déroulante des prénoms en conservant la sélection courante.
function peRemplirPrenoms(noms,selection,selectId){
  const sel=document.getElementById(selectId||'pe-edit-prenom');
  if(!sel)return;
  const liste=[...new Set(noms)].filter(Boolean)
    .sort((a,b)=>a.localeCompare(b,'fr',{sensitivity:'base'}));
  sel.innerHTML='<option value="">-- Choisir --</option>'
    +liste.map(n=>'<option value="'+escHtml(n)+'">'+escHtml(n)+'</option>').join('')
    +'<option value="__autre__">Autre (saisir)…</option>';
  if(selection&&liste.includes(selection))sel.value=selection;
  return liste;
}

async function peOpenCellEdit(eventId,creneauLabel,jourStr,crecheId,semaine){
  const jour=parseInt(jourStr);
  _peEditCtx={eventId:eventId||null,creneauLabel,jour,crecheId,semaine};

  const cached=_peCache[crecheId+'_'+semaine]||[];
  const ev=eventId?cached.find(r=>r.id===eventId):null;
  const courant=ev?ev.prenom:'';

  // Liste immédiate : les prénoms présents dans la semaine affichée.
  peRemplirPrenoms(cached.map(r=>r.prenom).concat(courant?[courant]:[]),courant);

  document.getElementById('pe-edit-prenom-autre').value='';
  document.getElementById('pe-edit-prenom-autre').style.display='none';
  document.getElementById('pe-edit-creneau-label').textContent=creneauLabel+' — '+DAYS[jour];
  if(eventId){
    document.getElementById('pe-edit-title').textContent='Modifier le créneau';
    document.getElementById('pe-edit-delete-btn').style.display='';
  }else{
    document.getElementById('pe-edit-title').textContent='Ajouter sur ce créneau';
    document.getElementById('pe-edit-delete-btn').style.display='none';
  }
  document.getElementById('modal-pe-edit-wrap').classList.add('open');

  // Puis on élargit : la semaine affichée ne contient que les personnes déjà
  // planifiées CETTE semaine-là. Quelqu'un qui n'y travaille pas (congés,
  // arrivée en cours de mois, semaine encore vide) en était absent et devenait
  // impossible à ajouter autrement qu'en le retapant via « Autre ».
  // On y ajoute donc tous les prénoms connus de la crèche, toutes semaines
  // confondues, ainsi que les directrices techniques qui y sont rattachées.
  try{
    const connus=(typeof spPrenomsConnus==='function')?await spPrenomsConnus(crecheId):[];
    const refs=(cacheReferents||[])
      .filter(r=>r.creche_id===crecheId&&r.name)
      .map(r=>String(r.name).trim().split(/\s+/)[0]);
    // La modale a pu être refermée pendant la requête.
    if(!_peEditCtx||_peEditCtx.crecheId!==crecheId||_peEditCtx.semaine!==semaine)return;
    const sel=document.getElementById('pe-edit-prenom');
    const choixActuel=sel?sel.value:'';
    peRemplirPrenoms(
      cached.map(r=>r.prenom).concat(connus,refs,courant?[courant]:[]),
      (choixActuel&&choixActuel!=='__autre__')?choixActuel:courant
    );
    if(choixActuel==='__autre__'&&sel)sel.value='__autre__';
  }catch(e){console.error('[PlanningEquipe] liste prénoms',e);}
}

function peOnPrenomChange(){
  const v=document.getElementById('pe-edit-prenom').value;
  document.getElementById('pe-edit-prenom-autre').style.display=v==='__autre__'?'':'none';
}

async function peSaveCellEdit(){
  if(!_peEditCtx)return;
  const sel=document.getElementById('pe-edit-prenom').value;
  const prenom=sel==='__autre__'?document.getElementById('pe-edit-prenom-autre').value.trim():sel;
  if(!prenom){alert('Choisissez ou saisissez un prénom.');return;}

  const{eventId,creneauLabel,jour,crecheId,semaine}=_peEditCtx;
  const creneau=ipParseCreneauLabel(creneauLabel);
  const prevRow=eventId?(_peCache[crecheId+'_'+semaine]||[]).find(r=>r.id===eventId):null;
  const prevPrenom=prevRow?prevRow.prenom:null;
  const btn=document.querySelector('#modal-pe-edit-wrap .btn-primary');
  if(btn){btn.disabled=true;btn.innerHTML='<i class="ti ti-loader"></i> Enregistrement…';}

  let error;
  if(eventId){
    ({error}=await sb.from('planning_equipe').update({prenom}).eq('id',eventId));
  }else{
    ({error}=await sb.from('planning_equipe').insert({
      creche_id:crecheId,prenom,semaine,jour,type:'presence',label:prenom,
      lieu:null,hdebut:creneau?.hdebut||null,hfin:creneau?.hfin||null,pause:creneau?.pause||null,
      creneau_label:creneauLabel
    }));
  }

  if(btn){btn.disabled=false;btn.innerHTML='<i class="ti ti-check"></i> Enregistrer';}
  if(error){console.error('[PlanningEquipe] edit:',error.message);showBanner('Erreur lors de l\'enregistrement.','error');return;}

  if(prevPrenom&&prevPrenom!==prenom)await peUnsyncReferentPlanning(crecheId,semaine,jour,prevPrenom);
  await peSyncReferentPlanning(crecheId,semaine,jour,prenom,{
    type:'presence',label:prenom,lieu:null,hdebut:creneau?.hdebut||null,hfin:creneau?.hfin||null,pause:creneau?.pause||null
  });

  peInvalidate(crecheId,semaine);
  closeModal('modal-pe-edit-wrap');
  await renderPlanning();
  showBanner(prenom+' enregistré(e) ✅');
}

async function peDeleteCellEdit(){
  if(!_peEditCtx||!_peEditCtx.eventId)return;
  if(!confirm('Retirer cette personne de ce créneau ?'))return;
  const{eventId,jour,crecheId,semaine}=_peEditCtx;
  const removedRow=(_peCache[crecheId+'_'+semaine]||[]).find(r=>r.id===eventId);
  const{error}=await sb.from('planning_equipe').delete().eq('id',eventId);
  if(error){console.error('[PlanningEquipe] delete:',error.message);showBanner('Erreur lors de la suppression.','error');return;}
  if(removedRow)await peUnsyncReferentPlanning(crecheId,semaine,jour,removedRow.prenom);
  peInvalidate(crecheId,semaine);
  closeModal('modal-pe-edit-wrap');
  await renderPlanning();
  showBanner('Créneau libéré ✅');
}

// ── CRÉATION MANUELLE D'UN CRÉNEAU (construire le planning à la main, sans import) ──
function peTimeToLabel(hhmm){return String(hhmm||'').replace(':','h');}

async function peOpenNewCreneau(){
  if(!_peCurCrecheId||!_peCurEditable)return;
  const joursWrap=document.getElementById('pe-nc-jours');
  joursWrap.innerHTML=DAYS.map((d,i)=>'<label style="display:flex;align-items:center;gap:4px;font-size:12px;background:#F5F4FA;border-radius:8px;padding:5px 9px;cursor:pointer"><input type="checkbox" class="pe-nc-jour-cb" value="'+i+'"> '+d+'</label>').join('');
  document.getElementById('pe-nc-hdebut').value='08:00';
  document.getElementById('pe-nc-hfin').value='18:00';
  document.getElementById('pe-nc-pause-toggle').checked=false;
  document.getElementById('pe-nc-pause-wrap').style.display='none';
  document.getElementById('pe-nc-pause-debut').value='12:30';
  document.getElementById('pe-nc-pause-fin').value='14:00';
  document.getElementById('pe-nc-prenom-autre').value='';
  document.getElementById('pe-nc-prenom-autre').style.display='none';

  const cached=_peCache[_peCurCrecheId+'_'+_peCurSemaine]||[];
  peRemplirPrenoms(cached.map(r=>r.prenom),'','pe-nc-prenom');
  document.getElementById('modal-pe-new-creneau-wrap').classList.add('open');

  try{
    const connus=(typeof spPrenomsConnus==='function')?await spPrenomsConnus(_peCurCrecheId):[];
    const refs=(cacheReferents||[]).filter(r=>r.creche_id===_peCurCrecheId&&r.name).map(r=>String(r.name).trim().split(/\s+/)[0]);
    if(!document.getElementById('modal-pe-new-creneau-wrap').classList.contains('open'))return;
    peRemplirPrenoms(cached.map(r=>r.prenom).concat(connus,refs),'','pe-nc-prenom');
  }catch(e){console.error('[PlanningEquipe] liste prénoms',e);}
}

function peNcTogglePause(){
  document.getElementById('pe-nc-pause-wrap').style.display=document.getElementById('pe-nc-pause-toggle').checked?'flex':'none';
}
function peNcOnPrenomChange(){
  const v=document.getElementById('pe-nc-prenom').value;
  document.getElementById('pe-nc-prenom-autre').style.display=v==='__autre__'?'':'none';
}

async function peSaveNewCreneau(){
  if(!_peCurCrecheId||!_peCurSemaine)return;
  const jours=[...document.querySelectorAll('.pe-nc-jour-cb:checked')].map(cb=>parseInt(cb.value,10));
  if(!jours.length){alert('Choisissez au moins un jour.');return;}
  const hdebut=document.getElementById('pe-nc-hdebut').value;
  const hfin=document.getElementById('pe-nc-hfin').value;
  if(!hdebut||!hfin){alert('Renseignez les heures de début et de fin.');return;}
  const avecPause=document.getElementById('pe-nc-pause-toggle').checked;
  const pauseDebut=document.getElementById('pe-nc-pause-debut').value;
  const pauseFin=document.getElementById('pe-nc-pause-fin').value;
  if(avecPause&&(!pauseDebut||!pauseFin)){alert('Renseignez la plage de pause, ou décochez-la.');return;}
  const sel=document.getElementById('pe-nc-prenom').value;
  const prenom=sel==='__autre__'?document.getElementById('pe-nc-prenom-autre').value.trim():sel;
  if(!prenom){alert('Choisissez ou saisissez un prénom.');return;}

  const creneauLabel=avecPause
    ?peTimeToLabel(hdebut)+'-'+peTimeToLabel(pauseDebut)+'/'+peTimeToLabel(pauseFin)+'-'+peTimeToLabel(hfin)
    :peTimeToLabel(hdebut)+'-'+peTimeToLabel(hfin);
  const pause=avecPause?(pauseDebut+'-'+pauseFin):null;

  const btn=document.querySelector('#modal-pe-new-creneau-wrap .btn-primary');
  if(btn){btn.disabled=true;btn.innerHTML='<i class="ti ti-loader"></i> Enregistrement…';}
  const rowsToInsert=jours.map(jour=>({
    creche_id:_peCurCrecheId,prenom,semaine:_peCurSemaine,jour,type:'presence',label:prenom,
    lieu:null,hdebut,hfin,pause,creneau_label:creneauLabel
  }));
  const{error}=await sb.from('planning_equipe').insert(rowsToInsert);
  if(btn){btn.disabled=false;btn.innerHTML='<i class="ti ti-check"></i> Ajouter';}
  if(error){console.error('[PlanningEquipe] new:',error.message);showBanner('Erreur lors de l\'enregistrement.','error');return;}

  for(const jour of jours){
    await peSyncReferentPlanning(_peCurCrecheId,_peCurSemaine,jour,prenom,{type:'presence',label:prenom,lieu:null,hdebut,hfin,pause});
  }

  peInvalidate(_peCurCrecheId,_peCurSemaine);
  closeModal('modal-pe-new-creneau-wrap');
  await renderPlanning();
  showBanner('Créneau ajouté ✅');
}

// ── DUPLICATION D'UN JOUR VERS D'AUTRES JOURS (même semaine) ──
let _peDupDaySource=null;
function peOpenDuplicateDay(dayIndex){
  if(!_peCurCrecheId||!_peCurEditable)return;
  _peDupDaySource=dayIndex;
  document.getElementById('pe-dup-day-sub').textContent='Copier le contenu du '+DAYS[dayIndex]+' vers :';
  const wrap=document.getElementById('pe-dup-day-targets');
  wrap.innerHTML=DAYS.map((d,i)=>i===dayIndex?'':'<label style="display:flex;align-items:center;gap:4px;font-size:12px;background:#F5F4FA;border-radius:8px;padding:5px 9px;cursor:pointer"><input type="checkbox" class="pe-dup-day-cb" value="'+i+'"> '+d+'</label>').join('');
  document.getElementById('pe-dup-day-replace').checked=true;
  document.getElementById('modal-pe-dup-day-wrap').classList.add('open');
}
async function peSaveDuplicateDay(){
  if(_peDupDaySource==null||!_peCurCrecheId||!_peCurSemaine)return;
  const targets=[...document.querySelectorAll('.pe-dup-day-cb:checked')].map(cb=>parseInt(cb.value,10));
  if(!targets.length){alert('Choisissez au moins un jour de destination.');return;}
  const replace=document.getElementById('pe-dup-day-replace').checked;

  const btn=document.querySelector('#modal-pe-dup-day-wrap .btn-primary');
  if(btn){btn.disabled=true;btn.innerHTML='<i class="ti ti-loader"></i> Duplication…';}

  const cached=await peLoad(_peCurCrecheId,_peCurSemaine);
  const sourceRows=cached.filter(r=>r.jour===_peDupDaySource);
  if(!sourceRows.length){
    if(btn){btn.disabled=false;btn.innerHTML='<i class="ti ti-check"></i> Dupliquer';}
    showBanner('Aucun créneau à dupliquer sur ce jour.','error');
    return;
  }

  if(replace){
    const oldTargetRows=cached.filter(r=>targets.includes(r.jour));
    const{error:errDel}=await sb.from('planning_equipe').delete().eq('creche_id',_peCurCrecheId).eq('semaine',_peCurSemaine).in('jour',targets);
    if(errDel){console.error('[PlanningEquipe] dup day del:',errDel.message);showBanner('Erreur lors du remplacement.','error');if(btn){btn.disabled=false;btn.innerHTML='<i class="ti ti-check"></i> Dupliquer';}return;}
    for(const r of oldTargetRows)await peUnsyncReferentPlanning(_peCurCrecheId,_peCurSemaine,r.jour,r.prenom);
  }

  const rowsToInsert=[];
  targets.forEach(jour=>sourceRows.forEach(r=>rowsToInsert.push({
    creche_id:_peCurCrecheId,prenom:r.prenom,semaine:_peCurSemaine,jour,type:r.type||'presence',label:r.label||r.prenom,
    lieu:r.lieu||null,hdebut:r.hdebut||null,hfin:r.hfin||null,pause:r.pause||null,creneau_label:r.creneau_label||null
  })));
  const{error}=await sb.from('planning_equipe').insert(rowsToInsert);
  if(btn){btn.disabled=false;btn.innerHTML='<i class="ti ti-check"></i> Dupliquer';}
  if(error){console.error('[PlanningEquipe] dup day:',error.message);showBanner('Erreur lors de la duplication.','error');return;}

  for(const jour of targets){
    for(const r of sourceRows){
      await peSyncReferentPlanning(_peCurCrecheId,_peCurSemaine,jour,r.prenom,{type:r.type,label:r.label||r.prenom,lieu:r.lieu,hdebut:r.hdebut,hfin:r.hfin,pause:r.pause});
    }
  }

  peInvalidate(_peCurCrecheId,_peCurSemaine);
  closeModal('modal-pe-dup-day-wrap');
  await renderPlanning();
  showBanner('Journée dupliquée ✅');
}

// ── DUPLICATION DE LA SEMAINE AFFICHÉE VERS LES SEMAINES SUIVANTES ──
function peOpenDuplicateWeek(){
  if(!_peCurCrecheId||!_peCurEditable)return;
  const ws=new Date(_peCurSemaine+'T00:00:00');
  document.getElementById('pe-dup-week-sub').textContent='Copier la semaine du '+ws.toLocaleDateString('fr-FR')+' sur les semaines suivantes.';
  document.getElementById('pe-dup-week-count').value='1';
  document.getElementById('pe-dup-week-replace').checked=true;
  document.getElementById('modal-pe-dup-week-wrap').classList.add('open');
}
async function peSaveDuplicateWeek(){
  if(!_peCurCrecheId||!_peCurSemaine)return;
  const count=Math.max(1,Math.min(12,parseInt(document.getElementById('pe-dup-week-count').value,10)||1));
  const replace=document.getElementById('pe-dup-week-replace').checked;

  const btn=document.querySelector('#modal-pe-dup-week-wrap .btn-primary');
  if(btn){btn.disabled=true;btn.innerHTML='<i class="ti ti-loader"></i> Duplication…';}

  const sourceRows=await peLoad(_peCurCrecheId,_peCurSemaine);
  if(!sourceRows.length){
    if(btn){btn.disabled=false;btn.innerHTML='<i class="ti ti-check"></i> Dupliquer';}
    showBanner('Aucun créneau à dupliquer sur cette semaine.','error');
    return;
  }

  const baseDate=new Date(_peCurSemaine+'T00:00:00');
  for(let i=1;i<=count;i++){
    const targetDate=new Date(baseDate);targetDate.setDate(baseDate.getDate()+7*i);
    const targetSemaine=ipDateToLocalISO(targetDate);
    if(replace){
      const oldTargetRows=await peLoad(_peCurCrecheId,targetSemaine);
      const{error:errDel}=await sb.from('planning_equipe').delete().eq('creche_id',_peCurCrecheId).eq('semaine',targetSemaine);
      if(errDel){console.error('[PlanningEquipe] dup week del:',errDel.message);continue;}
      for(const r of oldTargetRows)await peUnsyncReferentPlanning(_peCurCrecheId,targetSemaine,r.jour,r.prenom);
    }
    const rowsToInsert=sourceRows.map(r=>({
      creche_id:_peCurCrecheId,prenom:r.prenom,semaine:targetSemaine,jour:r.jour,type:r.type||'presence',label:r.label||r.prenom,
      lieu:r.lieu||null,hdebut:r.hdebut||null,hfin:r.hfin||null,pause:r.pause||null,creneau_label:r.creneau_label||null
    }));
    const{error}=await sb.from('planning_equipe').insert(rowsToInsert);
    if(error)console.error('[PlanningEquipe] dup week:',error.message);
    for(const r of sourceRows){
      await peSyncReferentPlanning(_peCurCrecheId,targetSemaine,r.jour,r.prenom,{type:r.type,label:r.label||r.prenom,lieu:r.lieu,hdebut:r.hdebut,hfin:r.hfin,pause:r.pause});
    }
    peInvalidate(_peCurCrecheId,targetSemaine);
  }

  if(btn){btn.disabled=false;btn.innerHTML='<i class="ti ti-check"></i> Dupliquer';}
  closeModal('modal-pe-dup-week-wrap');
  await renderPlanning();
  showBanner(count>1?count+' semaines dupliquées ✅':'Semaine dupliquée ✅');
}

// ── GÉNÉRATION AUTOMATIQUE DU PLANNING PAR IA ──
// L'IA (edge function generer-planning-ia) reçoit le planning déjà réalisé sur
// N semaines et propose les semaines suivantes en respectant la rotation
// observée. Rien n'est écrit en base avant validation explicite (aperçu).
let _peIAProposal=null,_peIATargetWeeks=[]; // [{semaine, decalage}]

function peOpenIA(){
  if(!_peCurCrecheId||!_peCurEditable)return;
  document.getElementById('pe-ia-step-preview').style.display='none';
  document.getElementById('pe-ia-step-form').style.display='';
  document.getElementById('pe-ia-nb-source').value='4';
  document.getElementById('pe-ia-nb-target').value='4';
  // Par défaut : les 4 semaines qui précèdent celle affichée.
  const defStart=new Date(_peCurSemaine+'T00:00:00');defStart.setDate(defStart.getDate()-28);
  document.getElementById('pe-ia-source-start').value=ipDateToLocalISO(defStart);
  peIAUpdateSub();
  document.getElementById('modal-pe-ia-wrap').classList.add('open');
}

function peIAUpdateSub(){
  const startVal=document.getElementById('pe-ia-source-start').value;
  const nbSource=Math.max(1,Math.min(12,parseInt(document.getElementById('pe-ia-nb-source').value,10)||1));
  const nbTarget=Math.max(1,Math.min(12,parseInt(document.getElementById('pe-ia-nb-target').value,10)||1));
  const sub=document.getElementById('pe-ia-target-sub');
  if(!startVal||!sub){if(sub)sub.textContent='';return;}
  const start=new Date(startVal+'T00:00:00');
  const firstTarget=new Date(start);firstTarget.setDate(start.getDate()+7*nbSource);
  const lastTarget=new Date(firstTarget);lastTarget.setDate(firstTarget.getDate()+7*(nbTarget-1));
  sub.textContent='Semaines générées : du '+firstTarget.toLocaleDateString('fr-FR')+' au '+lastTarget.toLocaleDateString('fr-FR')+'.';
}

async function peLoadWeeksRange(crecheId,startSemaineISO,nbWeeks){
  const start=new Date(startSemaineISO+'T00:00:00');
  const out=[];
  for(let i=0;i<nbWeeks;i++){
    const d=new Date(start);d.setDate(start.getDate()+7*i);
    const semaine=ipDateToLocalISO(d);
    const rows=await peLoad(crecheId,semaine);
    out.push({semaine,rows});
  }
  return out;
}

async function peRunIA(){
  if(!_peCurCrecheId)return;
  const startVal=document.getElementById('pe-ia-source-start').value;
  if(!startVal){alert('Choisissez la semaine de départ des données à analyser.');return;}
  const nbSource=Math.max(1,Math.min(12,parseInt(document.getElementById('pe-ia-nb-source').value,10)||1));
  const nbTarget=Math.max(1,Math.min(12,parseInt(document.getElementById('pe-ia-nb-target').value,10)||1));

  const btn=document.querySelector('#pe-ia-step-form .btn-primary');
  if(btn){btn.disabled=true;btn.innerHTML='<i class="ti ti-loader"></i> Analyse en cours…';}

  try{
    const weeks=await peLoadWeeksRange(_peCurCrecheId,startVal,nbSource);
    const sourceRows=[];
    weeks.forEach((w,semaineIndex)=>{
      w.rows.filter(r=>r.creneau_label).forEach(r=>{
        sourceRows.push({semaineIndex,jour:r.jour,prenom:r.prenom,heureDebut:r.hdebut||null,heureFin:r.hfin||null,pause:r.pause||null});
      });
    });
    if(!sourceRows.length){
      showBanner('Aucun créneau dans les semaines sélectionnées : rien à analyser.','error');
      return;
    }

    const lastSourceDate=new Date(startVal+'T00:00:00');lastSourceDate.setDate(lastSourceDate.getDate()+7*nbSource);
    _peIATargetWeeks=Array.from({length:nbTarget},(_,i)=>{
      const d=new Date(lastSourceDate);d.setDate(lastSourceDate.getDate()+7*i);
      return{decalage:i,semaine:ipDateToLocalISO(d)};
    });

    const r=await fetch(SUPABASE_URL+'/functions/v1/generer-planning-ia',{
      method:'POST',
      headers:{'Content-Type':'application/json','Authorization':'Bearer '+SUPABASE_ANON_KEY},
      body:JSON.stringify({crecheName:_peCurCrecheName,nbSemainesSource:nbSource,nbSemainesAGenerer:nbTarget,sourceRows})
    });
    const data=await r.json().catch(()=>null);
    if(!r.ok||!data||!Array.isArray(data.semaines)){
      showBanner((data&&data.error)?data.error:'Erreur lors de la génération IA.','error');
      return;
    }

    _peIAProposal=data;
    peRenderIAPreview(data);
    document.getElementById('pe-ia-step-form').style.display='none';
    document.getElementById('pe-ia-step-preview').style.display='';
  }catch(err){
    console.error('[PlanningEquipe IA]',err);
    showBanner('Erreur réseau lors de la génération IA.','error');
  }finally{
    if(btn){btn.disabled=false;btn.innerHTML='<i class="ti ti-sparkles"></i> Analyser et générer';}
  }
}

function peRenderIAPreview(data){
  document.getElementById('pe-ia-remarques').textContent=data.remarques||'';
  const body=document.getElementById('pe-ia-preview-body');
  const bySemaine=[...(_peIATargetWeeks||[])].sort((a,b)=>a.decalage-b.decalage);
  body.innerHTML=bySemaine.map(tw=>{
    const semObj=(data.semaines||[]).find(s=>s.decalageSemaines===tw.decalage);
    const creneaux=semObj?.creneaux||[];
    const wsDate=new Date(tw.semaine+'T00:00:00');
    const parJour=DAYS.map((d,i)=>({jour:d,items:creneaux.filter(c=>c.jour===i)}));
    return '<div style="margin-bottom:12px;border:1px solid var(--border);border-radius:8px;padding:8px 10px">'
      +'<div style="font-size:12.5px;font-weight:700;color:var(--koala);margin-bottom:6px">Semaine du '+wsDate.toLocaleDateString('fr-FR')+'</div>'
      +(creneaux.length?parJour.map(pj=>pj.items.length?
        '<div style="font-size:12px;margin-bottom:3px"><strong>'+pj.jour+' :</strong> '+pj.items.map(c=>escHtml(c.prenom)+' ('+(c.heureDebut||'?')+'-'+(c.heureFin||'?')+')').join(', ')+'</div>'
        :'').join('')
        :'<div style="font-size:12px;color:#bbb">Aucun créneau proposé.</div>')
      +'</div>';
  }).join('');
}

function peIABackToForm(){
  document.getElementById('pe-ia-step-preview').style.display='none';
  document.getElementById('pe-ia-step-form').style.display='';
}

async function peValidateIA(){
  if(!_peIAProposal||!_peCurCrecheId)return;
  const replace=document.getElementById('pe-ia-replace').checked;
  const btn=document.querySelector('#pe-ia-step-preview .btn-primary');
  if(btn){btn.disabled=true;btn.innerHTML='<i class="ti ti-loader"></i> Écriture…';}

  for(const tw of _peIATargetWeeks){
    const semObj=(_peIAProposal.semaines||[]).find(s=>s.decalageSemaines===tw.decalage);
    const creneaux=semObj?.creneaux||[];
    if(!creneaux.length)continue;
    if(replace){
      const oldTargetRows=await peLoad(_peCurCrecheId,tw.semaine);
      const{error:errDel}=await sb.from('planning_equipe').delete().eq('creche_id',_peCurCrecheId).eq('semaine',tw.semaine);
      if(errDel){console.error('[PlanningEquipe IA] del:',errDel.message);continue;}
      for(const r of oldTargetRows)await peUnsyncReferentPlanning(_peCurCrecheId,tw.semaine,r.jour,r.prenom);
    }
    const rowsToInsert=creneaux.map(c=>{
      const avecPause=c.pauseDebut&&c.pauseFin;
      const creneauLabel=avecPause
        ?peTimeToLabel(c.heureDebut)+'-'+peTimeToLabel(c.pauseDebut)+'/'+peTimeToLabel(c.pauseFin)+'-'+peTimeToLabel(c.heureFin)
        :peTimeToLabel(c.heureDebut)+'-'+peTimeToLabel(c.heureFin);
      return{
        creche_id:_peCurCrecheId,prenom:c.prenom,semaine:tw.semaine,jour:c.jour,type:'presence',label:c.prenom,
        lieu:null,hdebut:c.heureDebut||null,hfin:c.heureFin||null,pause:avecPause?(c.pauseDebut+'-'+c.pauseFin):null,creneau_label:creneauLabel
      };
    });
    const{error}=await sb.from('planning_equipe').insert(rowsToInsert);
    if(error)console.error('[PlanningEquipe IA] insert:',error.message);
    for(const c of creneaux){
      const avecPause=c.pauseDebut&&c.pauseFin;
      await peSyncReferentPlanning(_peCurCrecheId,tw.semaine,c.jour,c.prenom,{
        type:'presence',label:c.prenom,lieu:null,hdebut:c.heureDebut||null,hfin:c.heureFin||null,
        pause:avecPause?(c.pauseDebut+'-'+c.pauseFin):null
      });
    }
    peInvalidate(_peCurCrecheId,tw.semaine);
  }

  if(btn){btn.disabled=false;btn.innerHTML='<i class="ti ti-check"></i> Écrire dans le planning';}
  closeModal('modal-pe-ia-wrap');
  await renderPlanning();
  showBanner('Planning généré par IA ✅');
}

let _peCurCrecheId=null,_peCurSemaine=null,_peCurEditable=false,_peCurCrecheName='';
async function renderPlanningEquipe(){
  const sel=document.getElementById('pe-creche-select');
  const wrap=document.getElementById('pe-grid-wrap');
  if(!sel||!wrap)return;

  let crecheId;
  if(isDirection){
    sel.style.display='';
    if(sel.options.length<=1){
      sel.innerHTML='<option value="">-- Choisir une crèche --</option>'+cacheCreches.map(c=>'<option value="'+c.id+'">'+c.name+'</option>').join('');
    }
    crecheId=sel.value;
  }else{
    sel.style.display='none';
    crecheId=currentProfile?.creche_id;
  }

  if(!crecheId){
    wrap.innerHTML='<div style="text-align:center;padding:2rem;color:#bbb;font-size:13px">Sélectionnez une crèche</div>';
    const ncBtn0=document.getElementById('pe-new-creneau-btn'),dwBtn0=document.getElementById('pe-dup-week-btn'),iaBtn0=document.getElementById('pe-ia-btn'),rsBtn0=document.getElementById('pe-resync-btn');
    if(ncBtn0)ncBtn0.style.display='none';
    if(dwBtn0)dwBtn0.style.display='none';
    if(iaBtn0)iaBtn0.style.display='none';
    if(rsBtn0)rsBtn0.style.display='none';
    return;
  }

  const ws=weekStart();const semaine=ipDateToLocalISO(ws);
  if(!_syncSilencieuse)wrap.innerHTML='<div style="padding:1rem;text-align:center;color:#bbb;font-size:12px">Chargement…</div>';
  const rows=await peLoad(crecheId,semaine);
  await peLoadRemplacantes(crecheId,semaine);
  const crecheName=cacheCreches.find(c=>c.id===crecheId)?.name||'';
  // Éditable pour : la direction, OU la directrice technique dont la propre crèche correspond à celle affichée
  const editable=isDirection||(currentProfile?.creche_id===crecheId);
  _peCurCrecheId=crecheId;_peCurSemaine=semaine;_peCurEditable=editable;_peCurCrecheName=crecheName;
  const peBadge=document.getElementById('pe-badge');
  if(peBadge){
    if(editable){peBadge.textContent='✏️ Modifiable';peBadge.style.background='var(--koala-light)';peBadge.style.color='var(--koala)';}
    else{peBadge.textContent='👁 Lecture seule';peBadge.style.background='#f0f0f5';peBadge.style.color='#888';}
  }
  const ncBtn=document.getElementById('pe-new-creneau-btn'),dwBtn=document.getElementById('pe-dup-week-btn'),iaBtn=document.getElementById('pe-ia-btn'),rsBtn=document.getElementById('pe-resync-btn');
  if(ncBtn)ncBtn.style.display=editable?'':'none';
  if(dwBtn)dwBtn.style.display=(editable&&rows.length)?'':'none';
  if(iaBtn)iaBtn.style.display=editable?'':'none';
  if(rsBtn)rsBtn.style.display=(editable&&rows.length)?'':'none';
  peRenderRefNomRow(crecheId,editable);
  const _peFermBanner=(function(){
    const jrs=Array.from({length:5},(_,i)=>{const d=new Date(ws);d.setDate(ws.getDate()+i);return d;})
      .map(function(d){return fermetureAt(crecheId,ipDateToLocalISO(d));})
      .filter(Boolean);
    if(!jrs.length)return'';
    const uniq=[...new Set(jrs.map(fermetureLabel))];
    return '<div class="warn" style="background:var(--red-l,#FDE8E8);color:var(--red,#C62828);border-radius:12px;padding:9px 13px;font-size:12.5px;font-weight:700;margin-bottom:10px;display:flex;align-items:center;gap:7px"><i class="ti ti-door-off"></i> Crèche fermée cette semaine — '+escHtml(uniq.join(', '))+'</div>';
  })();
  wrap.innerHTML=_peFermBanner+getPlanningEquipeTable(rows,semaine,crecheName,crecheId,editable);

  const info=document.getElementById('pe-import-info');
  if(info){
    info.innerHTML='';
    ipDateDernierImportPlanning(crecheId).then(function(d){
      // La crèche affichée a pu changer pendant la requête.
      if(document.getElementById('pe-creche-select')&&getPlanningEquipeCrecheId()!==crecheId)return;
      info.innerHTML=d?ipLibelleFraicheur('Importé le',d)
                      :'<span style="color:var(--muted)">Aucun import enregistré</span>';
    });
  }
}
function getPlanningEquipeCrecheId(){
  const sel=document.getElementById('pe-creche-select');
  return isDirection?(sel?sel.value:''):currentProfile?.creche_id;
}

function getPlanningEquipeTable(rows,semaine,crecheName,crecheId,editable,forPrint,nbWeeksOnPage){
  if(!rows.length){
    if(editable&&!forPrint){
      return '<div style="text-align:center;padding:2rem;color:#999;font-size:13px">Aucun créneau pour cette semaine.<br><span style="font-size:12px">Importez un fichier Excel/PDF, ou construisez le planning à la main.</span>'
        +'<div style="margin-top:12px"><button class="btn-primary" style="font-size:12px;padding:7px 14px" onclick="peOpenNewCreneau()"><i class="ti ti-plus"></i> Ajouter un créneau</button></div></div>';
    }
    return '<div style="text-align:center;padding:2rem;color:#bbb;font-size:13px">Aucune donnée pour cette semaine — importez un fichier Excel pour cette crèche.</div>';
  }

  const ws=new Date(semaine+'T00:00:00');
  const fmt=d=>d.toLocaleDateString('fr-FR',{day:'2-digit',month:'2-digit'});
  const days5=Array.from({length:5},(_,i)=>{const d=new Date(ws);d.setDate(ws.getDate()+i);return d;});

  // Couleur fixe et distincte par professionnelle : les prénoms présents dans cette crèche sont
  // triés alphabétiquement puis répartis à intervalle parfaitement régulier sur le cercle des
  // teintes (360°/n). Stable par prénom (même prénom = toujours la même position alphabétique =
  // toujours la même couleur), et garantit l'écart maximal possible entre toutes les personnes
  // affichées ensemble — pas de collision même avec une équipe nombreuse.
  const _peNamesSorted=[...new Set(rows.map(r=>(r.prenom||'').trim()))].sort((a,b)=>a.localeCompare(b,'fr'));
  const _peColorCache={};
  function peColorForName(prenom){
    const key=(prenom||'').trim();
    if(_peColorCache[key])return _peColorCache[key];
    const idx=_peNamesSorted.indexOf(key);
    const n=_peNamesSorted.length||1;
    const hue=Math.round((idx<0?0:idx)*360/n);
    const color='hsl('+hue+',62%,28%)';
    _peColorCache[key]=color;
    return color;
  }

  // Sépare les événements qui ont un créneau horaire identifiable (ligne classique du fichier)
  // de ceux qui n'en ont pas (fusion de 2 activités, congé, absence) — affichés à part.
  const withCreneau=rows.filter(r=>r.creneau_label);
  const withoutCreneau=rows.filter(r=>!r.creneau_label);

  // Lignes = créneaux distincts, triés par heure de début (déduite du premier événement de ce créneau)
  //
  // La clé de regroupement est le créneau NORMALISÉ (ses plages en minutes), pas
  // le libellé brut : deux sources écrivent le même horaire différemment
  // (« 10H30-13H00 / 14H00-18H30 » venant de l'Excel, « 10h30-13h00/14h00-18h30 »
  // venant de l'import PDF). Regrouper sur le texte brut créait deux lignes
  // visuellement identiques dans le planning, avec les salariés répartis entre
  // les deux. On garde le premier libellé rencontré pour l'affichage et l'édition.
  const creneauOrder=[];
  const byCreneau={};
  const labelOf={};
  const peCreneauKey=lbl=>{
    const segs=peCreneauSegments(lbl);
    return segs?segs.map(s=>s[0]+'-'+s[1]).join('|'):'brut:'+String(lbl||'').toUpperCase().replace(/\s+/g,'');
  };
  withCreneau.forEach(r=>{
    const k=peCreneauKey(r.creneau_label);
    if(!byCreneau[k]){byCreneau[k]=[];labelOf[k]=r.creneau_label;creneauOrder.push(k);}
    byCreneau[k].push(r);
  });
  creneauOrder.sort((a,b)=>{
    const ha=byCreneau[a][0].hdebut||'99:99',hb=byCreneau[b][0].hdebut||'99:99';
    return ha.localeCompare(hb);
  });

  function renderCell(ev,crecheName){
    if(!ev)return '<span style="color:#ddd">—</span>';
    const color=peColorForName(ev.prenom);
    const ailleurs=ev.lieu&&ev.lieu!==crecheName;
    const clickAttr=editable?'onclick="peOpenCellEdit(\''+ev.id+'\',\''+ev.creneau_label.replace(/'/g,"\\'")+'\',\''+ev.jour+'\',\''+crecheId+'\',\''+semaine+'\')" style="cursor:pointer;'+'background:'+color+';color:#fff;border-radius:4px;padding:'+_peBadgePad+';font-size:'+_peFSCell+';text-align:center"':'style="background:'+color+';color:#fff;border-radius:4px;padding:'+_peBadgePad+';font-size:'+_peFSCell+';text-align:center"';
    return '<div '+clickAttr+'>'+
      '<strong>'+ev.prenom+'</strong>'+(ailleurs?' <span style="opacity:0.85">('+ev.lieu+')</span>':'')+
      '</div>';
  }

  // Tailles adaptées selon contexte écran/impression. Quand plusieurs semaines partagent la même
  // page (impression portrait compacte), les cases sont plus resserrées pour que tout tienne.
  nbWeeksOnPage=nbWeeksOnPage||1;
  const _peTier=!forPrint?'screen':(nbWeeksOnPage>=4?'p4':nbWeeksOnPage===3?'p3':nbWeeksOnPage===2?'p2':'p1');
  const _peSizes={
    screen:{fs:'12px',fsCell:'11px',fsDay:'10px',pad:'8px',padCell:'6px',horW:'150px',lh:'1.3',minW:'700px',badgePad:'4px 6px'},
    p1:    {fs:'15px',fsCell:'14px',fsDay:'13px',pad:'16px 14px',padCell:'14px 10px',horW:'230px',lh:'1.6',minW:'1100px',badgePad:'9px 12px'},
    p2:    {fs:'13px',fsCell:'12px',fsDay:'11px',pad:'8px 7px',padCell:'7px 6px',horW:'105px',lh:'1.35',minW:'560px',badgePad:'5px 7px'},
    p3:    {fs:'11px',fsCell:'10px',fsDay:'9px',pad:'6px 5px',padCell:'5px 4px',horW:'88px',lh:'1.25',minW:'490px',badgePad:'4px 6px'},
    p4:    {fs:'10px',fsCell:'9px',fsDay:'8px',pad:'4px 4px',padCell:'4px 3px',horW:'75px',lh:'1.15',minW:'440px',badgePad:'3px 5px'}
  };
  const _peS=_peSizes[_peTier];
  const _peFS=_peS.fs,_peFSCell=_peS.fsCell,_peFSDay=_peS.fsDay,_pePad=_peS.pad,_pePadCell=_peS.padCell,
        _peHoraireW=_peS.horW,_peRowLH=_peS.lh,_peMinW=_peS.minW,_peBadgePad=_peS.badgePad;
  // Chaque plage du créneau est rendue sur sa propre ligne (jamais de césure au milieu d'une heure).
  const _peCreneauLabel=c=>peRenderCreneau(c,_peFSCell,_peFSDay);

  let html='<table style="width:100%;border-collapse:collapse;font-size:'+_peFS+';'+(forPrint?'':'min-width:'+_peMinW+';')+'table-layout:fixed;line-height:'+_peRowLH+'">';
  const _peHorPct=16;
  html+='<colgroup><col style="width:'+_peHorPct+'%">'+DAYS.map(()=>'<col style="width:'+((100-_peHorPct)/5)+'%">').join('')+'</colgroup>';
  html+='<thead><tr><th style="position:sticky;left:0;z-index:2;padding:'+_pePad+';border-bottom:2px solid var(--border);text-align:left;background:#fafafa;color:#333;white-space:nowrap">Horaire</th>';
  DAYS.forEach((d,i)=>{
    const dupIcon=(editable&&!forPrint)?' <i class="ti ti-copy" style="cursor:pointer;opacity:0.55;font-size:'+_peFSDay+'" title="Dupliquer ce jour vers d\'autres jours" onclick="event.stopPropagation();peOpenDuplicateDay('+i+')"></i>':'';
    const _fermD=fermetureAt(crecheId,ipDateToLocalISO(days5[i]));
    html+='<th style="padding:'+_pePad+';border-bottom:2px solid var(--border);text-align:center;background:'+(_fermD?'var(--red-l,#FDE8E8)':'#fafafa')+';color:'+(_fermD?'var(--red,#C62828)':'#333')+'" title="'+(_fermD?escHtml(fermetureLabel(_fermD)):'')+'">'+d+dupIcon+'<br><span style="font-size:'+_peFSDay+';font-weight:400;opacity:0.7">'+fmt(days5[i])+'</span>'+(_fermD?'<br><span style="font-size:'+_peFSDay+';font-weight:800"><i class="ti ti-door-off"></i> Fermé</span>':'')+'</th>';
  });
  html+='</tr></thead><tbody>';

  creneauOrder.forEach(cleCreneau=>{
    const evsThisCreneau=byCreneau[cleCreneau];
    const creneau=labelOf[cleCreneau];
    const creneauEsc=String(creneau||'').replace(/'/g,"\\'");
    html+='<tr><td style="position:sticky;left:0;z-index:1;padding:'+_pePad+';border-bottom:1px solid var(--border);background:#FBFBFD;vertical-align:middle">'+_peCreneauLabel(creneau)+'</td>';
    for(let d=0;d<5;d++){
      // Plusieurs personnes peuvent partager le même créneau le même jour
      const evs=evsThisCreneau.filter(e=>e.jour===d);
      html+='<td style="padding:'+_pePadCell+';border-bottom:1px solid var(--border);word-wrap:break-word;overflow-wrap:break-word">';
      if(evs.length){
        html+=evs.map(e=>renderCell(e,crecheName)).join('<div style="height:4px"></div>');
        if(editable)html+='<div class="pe-add-more" onclick="peOpenCellEdit(null,\''+creneauEsc+'\',\''+d+'\',\''+crecheId+'\',\''+semaine+'\')" title="Ajouter quelqu\'un d\'autre sur ce créneau"><i class="ti ti-plus"></i></div>';
      }else if(editable){
        html+='<div class="pe-add-empty" onclick="peOpenCellEdit(null,\''+creneauEsc+'\',\''+d+'\',\''+crecheId+'\',\''+semaine+'\')">+ ajouter</div>';
      }else{
        html+='<div style="text-align:center"><span style="color:#ddd">—</span></div>';
      }
      html+='</td>';
    }
    html+='</tr>';
  });

  // Les lignes sans créneau (congé, absence, journées combinées) ne sont plus
  // rendues ici : elles alourdissaient le planning à l'écran comme à l'impression
  // sans porter d'horaire. Elles sont désormais remontées sur le dashboard
  // direction (carte « Autres activités du jour », loadDashboardAutres).
  // `withoutCreneau` reste calculé : il sert de compteur pour le pied de tableau.
  if(withoutCreneau.length){
    html+='<tr><td colspan="6" style="padding:'+_pePad+';font-size:'+_peFSDay+';color:var(--muted);font-style:italic;background:#FBFBFD">'
      +withoutCreneau.length+' activité(s) sans horaire (congé, absence, journée combinée) — voir « Absences et congés du jour » sur le dashboard</td></tr>';
  }

  // Continuité de direction : en l'absence de la directrice, la pro qui termine à 18h30
  // (directrice du matin) ou qui commence le plus tôt (directrice du soir) fait office de directeur.
  const _peCont=peContinuiteDirection(withCreneau,crecheId,semaine);
  if(_peCont.some(x=>x.length)){
    html+='<tr><td style="position:sticky;left:0;z-index:1;padding:'+_pePad+';border-top:2px solid var(--border);background:#FBFBFD;vertical-align:middle;font-weight:700;font-size:'+_peFSCell+';color:#3D3580"><i class="ti ti-shield-check"></i> Continuité de direction</td>';
    _peCont.forEach(x=>{
      html+='<td style="padding:'+_pePadCell+';border-top:2px solid var(--border);text-align:center;font-size:'+_peFSCell+';font-weight:700;color:#3D3580;background:#F4F3FB">'+(x.length?x.map(l=>escHtml(l)).join('<br>'):'<span style="color:#ddd;font-weight:400">—</span>')+'</td>';
    });
    html+='</tr>';
  }

  html+='</tbody></table>';
  return html;
}

const _peRemplCache={};
// Charge les noms de l'onglet Remplaçants/tes présents dans la crèche sur la semaine affichée.
async function peLoadRemplacantes(crecheId,semaine){
  const k=crecheId+'_'+semaine;
  const fin=new Date(semaine+'T00:00:00');fin.setDate(fin.getDate()+6);
  const{data,error}=await sb.from('remplacantes').select('nom').eq('creche_id',crecheId).gte('date',semaine).lte('date',ipDateToLocalISO(fin));
  if(error){console.warn('[PlanningEquipe] remplaçantes',error.message);return;}
  _peRemplCache[k]=new Set((data||[]).map(r=>ipNormStr(r.nom)));
}
// Une remplaçante ne peut pas être en continuité de direction : c'est l'autre pro qui prend le
// rôle. Elle est repérée par l'onglet Remplaçants/tes (prénom = nom saisi ou son premier mot),
// ou par une fiche employé de même prénom dont le poste / type de contrat contient « remplaçant/e ».
function peEstRemplacante(prenom,crecheId,semaine){
  const t=ipNormStr(prenom);
  if(!t)return false;
  const noms=_peRemplCache[crecheId+'_'+semaine];
  if(noms&&[...noms].some(n=>n===t||n.split(/\s+/)[0]===t))return true;
  return (cacheEmployes||[]).some(e=>ipNormStr(e.prenom)===t
    &&(!e.creche_id||e.creche_id===crecheId)
    &&ipNormStr((e.poste||'')+' '+(e.type_contrat||'')).includes('remplac'));
}

// Pour chaque jour (0-4), liste de lignes de texte de la continuité de direction.
// - Directrice présente, du matin (début avant 9h30) → la pro qui termine à 18h30.
// - Directrice présente, du soir → la pro qui commence à 7h30.
// - Directrice absente → la pro du matin (7h30) puis la pro du soir (18h30).
// Si un horaire n'a aucune pro éligible (remplaçante écartée), la pro de l'autre horaire la remplace.
function peContinuiteDirection(rows,crecheId,semaine){
  const out=[];
  for(let d=0;d<5;d++){
    const jour=rows.filter(r=>r.jour===d).map(r=>({r,segs:peCreneauSegments(r.creneau_label)})).filter(x=>x.segs);
    if(!jour.length){out.push([]);continue;}
    const noms=l=>[...new Set(l.map(x=>x.r.prenom))].join(', ');
    const dir=jour.filter(x=>peFindReferentIdForPrenom(crecheId,x.r.prenom,true));
    const dirNoms=new Set(dir.map(x=>ipNormStr(x.r.prenom)));
    const autres=jour.filter(x=>!dirNoms.has(ipNormStr(x.r.prenom))&&!peEstRemplacante(x.r.prenom,crecheId,semaine));
    // Ouverture = celle qui commence le plus tôt, fermeture = celle qui termine le plus tard
    // (hors directrice et remplaçantes) : les horaires ne tombent pas toujours pile à 7h30 / 18h30.
    const debutMin=autres.length?Math.min(...autres.map(x=>x.segs[0][0])):null;
    const finMax=autres.length?Math.max(...autres.map(x=>x.segs[x.segs.length-1][1])):null;
    let ouv=autres.filter(x=>x.segs[0][0]===debutMin);
    let fer=autres.filter(x=>x.segs[x.segs.length-1][1]===finMax);
    // Personne d'éligible sur un horaire (ex. remplaçante écartée) : la pro de l'autre horaire prend le rôle.
    if(!ouv.length)ouv=fer;
    if(!fer.length)fer=ouv;
    const lignes=[];
    if(!dir.length){
      if(ouv.length)lignes.push('Matin : '+noms(ouv));
      if(fer.length)lignes.push('Soir : '+noms(fer));
    }else{
      const matin=Math.min(...dir.map(x=>x.segs[0][0]))<570;
      const cand=matin?fer:ouv;
      if(cand.length)lignes.push(noms(cand));
    }
    out.push(lignes);
  }
  return out;
}

